package slidingwindow

import (
	"reflect"
	"testing"
)

func TestEmpty(t *testing.T) {
	result := SlidingWindowMax([]int{}, 3)
	if len(result) != 0 {
		t.Errorf("SlidingWindowMax([],3) = %v, want []", result)
	}
}

func TestSingle(t *testing.T) {
	result := SlidingWindowMax([]int{1}, 1)
	if !reflect.DeepEqual(result, []int{1}) {
		t.Errorf("SlidingWindowMax([1],1) = %v, want [1]", result)
	}
}

func TestClassic(t *testing.T) {
	result := SlidingWindowMax([]int{1, 3, -1, -3, 5, 3, 6, 7}, 3)
	want := []int{3, 3, 5, 5, 6, 7}
	if !reflect.DeepEqual(result, want) {
		t.Errorf("SlidingWindowMax = %v, want %v", result, want)
	}
}

func TestWindowTwo(t *testing.T) {
	result := SlidingWindowMax([]int{1, 2, 3, 4, 5}, 2)
	want := []int{2, 3, 4, 5}
	if !reflect.DeepEqual(result, want) {
		t.Errorf("SlidingWindowMax([1..5],2) = %v, want %v", result, want)
	}
}
